wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::state_read;

struct Node;

/// Percent-encodes a value for use as a query-string component (RFC 3986 unreserved set kept).
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment fetch, once per call. The input (`RunInfo`) has no `text`
        // field, so the only textual content available is `date`; it is used as
        // the query value. Adjust if the input contract is meant to carry other text.
        // The result is deliberately discarded so the output is unchanged.
        // A transport failure comes back as a value and is ignored; an
        // out-of-allowlist request traps at the boundary.
        let enrich_url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&info.date)
        );
        let _enrichment: Result<String, String> = http_client::fetch(&enrich_url);

        // Subscription lookup, unchanged. Key is the run date; the stored value
        // is one URL per line. A missing key yields an empty list.
        let urls: Vec<String> = match state_read::get(&info.date) {
            Some(value) => value
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
```

